changeSet.sql:
ALTER TABLE nexus.document_aspects NO FORCE ROW LEVEL SECURITY;

DO $$
DECLARE
    v_deleted_count BIGINT;
    v_backfilled_count BIGINT;
BEGIN
    DELETE FROM nexus.document_aspects WHERE doc_id IS NULL;
    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
    RAISE NOTICE 'hygiene-001-1: deleted % document_aspects row(s) with doc_id IS NULL', v_deleted_count;

    UPDATE nexus.document_aspects SET source_uri = '' WHERE source_uri IS NULL;
    GET DIAGNOSTICS v_backfilled_count = ROW_COUNT;
    RAISE NOTICE 'hygiene-001-1: backfilled % document_aspects.source_uri NULL row(s) to empty string', v_backfilled_count;
END $$;

ALTER TABLE nexus.document_aspects FORCE ROW LEVEL SECURITY;

ALTER TABLE nexus.document_aspects
    ALTER COLUMN doc_id SET NOT NULL,
    ALTER COLUMN source_uri SET NOT NULL;

ALTER TABLE nexus.aspect_extraction_queue NO FORCE ROW LEVEL SECURITY;

DO $$
DECLARE
    v_deleted_count BIGINT;
BEGIN
    DELETE FROM nexus.aspect_extraction_queue WHERE doc_id IS NULL;
    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
    RAISE NOTICE 'hygiene-001-2: deleted % aspect_extraction_queue row(s) with doc_id IS NULL', v_deleted_count;
END $$;

ALTER TABLE nexus.aspect_extraction_queue FORCE ROW LEVEL SECURITY;

ALTER TABLE nexus.aspect_extraction_queue ALTER COLUMN doc_id SET NOT NULL;

