DO $$
DECLARE
    v_deleted_count BIGINT;
BEGIN
    DELETE FROM nexus.document_highlights WHERE source_uri IS NULL OR collection IS NULL;
    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
    RAISE NOTICE 'hygiene-001-3: deleted % document_highlights row(s) with NULL source_uri or collection', v_deleted_count;
END $$;

ALTER TABLE nexus.document_highlights FORCE ROW LEVEL SECURITY;

ALTER TABLE nexus.document_highlights
    ALTER COLUMN source_uri SET NOT NULL,
    ALTER COLUMN collection SET NOT NULL;

ALTER TABLE nexus.catalog_documents NO FORCE ROW LEVEL SECURITY;

DO $$
DECLARE
    v_content_type BIGINT;
    v_physical_collection BIGINT;
    v_corpus BIGINT;
    v_file_path BIGINT;
    v_chunk_count BIGINT;
BEGIN
    UPDATE nexus.catalog_documents SET content_type = '' WHERE content_type IS NULL;
    GET DIAGNOSTICS v_content_type = ROW_COUNT;
    UPDATE nexus.catalog_documents SET physical_collection = '' WHERE physical_collection IS NULL;
    GET DIAGNOSTICS v_physical_collection = ROW_COUNT;
    UPDATE nexus.catalog_documents SET corpus = '' WHERE corpus IS NULL;
    GET DIAGNOSTICS v_corpus = ROW_COUNT;
    UPDATE nexus.catalog_documents SET file_path = '' WHERE file_path IS NULL;
    GET DIAGNOSTICS v_file_path = ROW_COUNT;
    UPDATE nexus.catalog_documents SET chunk_count = 0 WHERE chunk_count IS NULL;
    GET DIAGNOSTICS v_chunk_count = ROW_COUNT;
    RAISE NOTICE 'hygiene-001-4: backfilled catalog_documents NULL row(s) -- content_type=% physical_collection=% corpus=% file_path=% chunk_count=%',
        v_content_type, v_physical_collection, v_corpus, v_file_path, v_chunk_count;
END $$;

ALTER TABLE nexus.catalog_documents FORCE ROW LEVEL SECURITY;

ALTER TABLE nexus.catalog_documents
    ALTER COLUMN content_type SET DEFAULT '',
    ALTER COLUMN content_type SET NOT NULL,
    ALTER COLUMN physical_collection SET DEFAULT '',
    ALTER COLUMN physical_collection SET NOT NULL,
    ALTER COLUMN corpus SET DEFAULT '',
    ALTER COLUMN corpus SET NOT NULL,
    ALTER COLUMN file_path SET DEFAULT '',
    ALTER COLUMN file_path SET NOT NULL,
    ALTER COLUMN chunk_count SET DEFAULT 0,
    ALTER COLUMN chunk_count SET NOT NULL;

