changeSet.sql:
ALTER TABLE nexus.chunks NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.catalog_document_chunks NO FORCE ROW LEVEL SECURITY;

DO $$
DECLARE
    v_backfilled_count BIGINT;
    v_manifest_deleted_count BIGINT;
    v_deleted_count BIGINT;
BEGIN
    UPDATE nexus.chunks SET metadata = '{}'::jsonb
     WHERE metadata IS NULL AND octet_length(chash) = 32;
    GET DIAGNOSTICS v_backfilled_count = ROW_COUNT;
    RAISE NOTICE 'hygiene-001-5: backfilled % chunks.metadata NULL row(s) to {}', v_backfilled_count;

    -- FK safety ahead of the chunks DELETE below: catalog_document_chunks
    -- has no CASCADE toward chunks, so its rows referencing a doomed chunk
    -- must go first or the parent DELETE is rejected.
    DELETE FROM nexus.catalog_document_chunks cdc
     USING nexus.chunks c
     WHERE cdc.tenant_id = c.tenant_id
       AND cdc.collection = c.collection
       AND cdc.chash = c.chash
       AND (octet_length(c.chash) <> 32 OR c.chash IS NULL);
    GET DIAGNOSTICS v_manifest_deleted_count = ROW_COUNT;
    RAISE NOTICE 'hygiene-001-5: deleted % catalog_document_chunks manifest row(s) referencing an un-rekeyed legacy-width chunk (FK safety ahead of the chunks delete below)', v_manifest_deleted_count;

    DELETE FROM nexus.chunks WHERE octet_length(chash) <> 32 OR chash IS NULL;
    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
    RAISE NOTICE 'hygiene-001-5: deleted % chunks row(s) -- un-rekeyed legacy-width chash (RDR-180, nexus-lgdel deletion arc), unresolvable since the 32-byte cutover', v_deleted_count;
END $$;

ALTER TABLE nexus.catalog_document_chunks FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.chunks FORCE ROW LEVEL SECURITY;

ALTER TABLE nexus.chunks
    ALTER COLUMN metadata SET DEFAULT '{}'::jsonb,
    ALTER COLUMN metadata SET NOT NULL;

ALTER TABLE nexus.catalog_collections NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.catalog_documents NO FORCE ROW LEVEL SECURITY;

DO $$
DECLARE
    v_backfilled_count BIGINT;
BEGIN
    UPDATE nexus.catalog_collections c
       SET created_at = COALESCE(
               (SELECT min(d.indexed_at) FROM nexus.catalog_documents d
                 WHERE d.tenant_id = c.tenant_id
                   AND d.physical_collection = c.name),
               now())
     WHERE c.created_at IS NULL;
    GET DIAGNOSTICS v_backfilled_count = ROW_COUNT;
    RAISE NOTICE 'hygiene-001-6: backfilled % catalog_collections.created_at NULL row(s)', v_backfilled_count;
END $$;

ALTER TABLE nexus.catalog_documents FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.catalog_collections FORCE ROW LEVEL SECURITY;

ALTER TABLE nexus.catalog_collections
    ALTER COLUMN created_at SET DEFAULT now(),
    ALTER COLUMN created_at SET NOT NULL;

ALTER TABLE nexus.catalog_links NO FORCE ROW LEVEL SECURITY;

DO $$
DECLARE
    v_backfilled_count BIGINT;
BEGIN
    UPDATE nexus.catalog_links SET created_at = now() WHERE created_at IS NULL;
    GET DIAGNOSTICS v_backfilled_count = ROW_COUNT;
    RAISE NOTICE 'hygiene-001-7: backfilled % catalog_links.created_at NULL row(s) to now()', v_backfilled_count;
END $$;

ALTER TABLE nexus.catalog_links FORCE ROW LEVEL SECURITY;

ALTER TABLE nexus.catalog_links
    ALTER COLUMN created_at SET DEFAULT now(),
    ALTER COLUMN created_at SET NOT NULL;

ALTER TABLE nexus.catalog_document_chunks NO FORCE ROW LEVEL SECURITY;

DO $$
DECLARE
    v_backfilled_count BIGINT;
    v_deleted_count BIGINT;
BEGIN
    UPDATE nexus.catalog_document_chunks SET chunk_index = position
     WHERE chunk_index IS NULL AND octet_length(chash) = 32;
    GET DIAGNOSTICS v_backfilled_count = ROW_COUNT;
    RAISE NOTICE 'hygiene-001-8: backfilled % catalog_document_chunks.chunk_index NULL row(s) to position', v_backfilled_count;

    DELETE FROM nexus.catalog_document_chunks WHERE octet_length(chash) <> 32 OR chash IS NULL;
    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
    RAISE NOTICE 'hygiene-001-8: deleted % catalog_document_chunks row(s) -- un-rekeyed legacy-width chash (RDR-180, nexus-lgdel deletion arc), unresolvable since the 32-byte cutover', v_deleted_count;
END $$;

ALTER TABLE nexus.catalog_document_chunks FORCE ROW LEVEL SECURITY;

ALTER TABLE nexus.catalog_document_chunks ALTER COLUMN chunk_index SET NOT NULL;

-- CREATE TRIGGER takes the same ACCESS EXCLUSIVE lock as ALTER TABLE;
-- bound the wait exactly as the sibling steps do (review re-check).
SET LOCAL lock_timeout = '5s';
LOCK TABLE nexus.catalog_document_chunks IN ACCESS EXCLUSIVE MODE;
CREATE OR REPLACE FUNCTION nexus.default_chunk_index_from_position()
    RETURNS TRIGGER
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $fn$
BEGIN
    IF NEW.chunk_index IS NULL THEN
        NEW.chunk_index := NEW.position;
    END IF;
    RETURN NEW;
END;
$fn$;

CREATE TRIGGER trg_catalog_document_chunks_chunk_index_default
    BEFORE INSERT ON nexus.catalog_document_chunks
    FOR EACH ROW
    EXECUTE FUNCTION nexus.default_chunk_index_from_position();

