ALTER TABLE nexus.plans NO FORCE ROW LEVEL SECURITY;

DO $$
DECLARE
    v_deleted_count BIGINT;
BEGIN
    DELETE FROM nexus.plans
     WHERE ttl_days IS NOT NULL
       AND (extract(epoch from now() - coalesce(last_used, created_at)) / 86400) > ttl_days;
    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
    RAISE NOTICE 'hygiene-001-10: deleted % nexus.plans row(s) past their ttl_days -- read-filtered since nexus-sbl4m but never swept until now', v_deleted_count;
END $$;

ALTER TABLE nexus.plans FORCE ROW LEVEL SECURITY;

ALTER TABLE nexus.plans NO FORCE ROW LEVEL SECURITY;

DO $$
DECLARE
    v_deleted_count BIGINT;
BEGIN
    DELETE FROM nexus.plans WHERE verb IS NULL;
    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
    RAISE NOTICE 'hygiene-001-11: deleted % nexus.plans row(s) with verb IS NULL -- pre-nexus-fiovt shakeout residue', v_deleted_count;
END $$;

ALTER TABLE nexus.plans FORCE ROW LEVEL SECURITY;

ALTER TABLE nexus.plans ALTER COLUMN verb SET NOT NULL;
